<?php
declare(strict_types=1);require_once __DIR__.'/billing_common.php';$user=billing_require_admin();production_require_method('GET');accounts_endpoint(function():array{$db=production_db();$s=$db->query("SELECT w.*,r.reference_no,r.client_id,r.client_name_snapshot,r.receipt_date FROM qbook_receipt_wht w JOIN qbook_customer_receipts r ON r.id=w.receipt_id WHERE w.certificate_status='CERTIFICATE_PENDING' ORDER BY r.receipt_date,w.id");$rows=[];foreach($s->fetchAll()as$r){$r['receipt_reference']=billing_ref('RECEIPT',$r['reference_no']);$rows[]=$r;}return['certificates'=>$rows];});
